'use strict';

/**
* Perform the hermitian rank 1 operation `A = alpha*x*x**H + A`, where `alpha` is a real scalar, `x` is an `N` element vector and `A` is an `N` by `N` hermitian matrix.
*
* @module @stdlib/blas/base/zher
*
* @example
* var Complex128Array = require( '@stdlib/array/complex128' );
* var zher = require( '@stdlib/blas/base/zher' );
*
* var x = new Complex128Array( [ 1.0, 2.0, 3.0, 4.0 ] );
* var A = new Complex128Array( [ 1.0, 0.0, 0.0, 0.0, 2.0, 3.0, 4.0, 0.0 ] );
*
* zher( 'row-major', 'lower', x.length, 2.0, x, 1 A, 2 );
* // A => <Complex128Array>[ 11.0, 0.0, 0.0, 0.0, 24.0, -1.0, 54.0, 0.0 ]
*
* @example
* var Complex128Array = require( '@stdlib/array/complex128' );
* var zher = require( '@stdlib/blas/base/zher' );
*
* var x = new Complex128Array( [ 1.0, 2.0, 3.0, 4.0 ] );
* var A = new Complex128Array( [ 1.0, 0.0, 0.0, 0.0, 2.0, 3.0, 4.0, 0.0 ] );
*
* zher.ndarray( 'lower', x.length, 2.0, x, 1, 0, A, 2, 1, 0 );
* // A => <Complex128Array>[ 11.0, 0.0, 0.0, 0.0, 24.0, -1.0, 54.0, 0.0 ]
*/

// MODULES //

var join = require( 'path' ).join;
var tryRequire = require( '@stdlib/utils/try-require' );
var isError = require( '@stdlib/assert/is-error' );
var main = require( './main.js' );


// MAIN //

var zher;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	zher = main;
} else {
	zher = tmp;
}


// EXPORTS //

module.exports = zher;

// exports: { "ndarray": "zher.ndarray" }
